INSERT INTO `app_landing_page_translation` VALUES (1,1,'Accueil',NULL,NULL,NULL,NULL,'Groupe Brochard',NULL,'[{\"code\":\"app.component_slider\",\"data\":{\"title\":null,\"content\":null,\"template\":\"slider_default\",\"style\":\"hero\",\"cards\":[{\"section\":null,\"title\":\"Harum trium\",\"subtitle\":\"sententiarum nulli\",\"image\":\"/media/image/conceptarchitectsarchitectworkingblueprintoffice-620e736838f45.jpg\",\"alt\":\"Homme travaillant à un plan sur son bureau\",\"label\":\"En savoir plus\",\"link\":\"http://localhost:8887/fr_FR/\",\"content\":\"<p>Itaque tum Scaevola cum in eam ipsam mentionem incidisset,</p><p>exposuit nobis sermonem Laeli de amicitia habitum ab illo secum</p>\",\"template\":\"card_default\",\"style\":\"\"},{\"section\":null,\"title\":\"Harum trium\",\"subtitle\":\"sententiarum nulli\",\"image\":\"/media/image/croparchitectopeningblueprint_1-622a2c3216d02.png\",\"alt\":null,\"label\":\"En savoir plus\",\"link\":\"http://localhost:8887/fr_FR/\",\"content\":\"<p>Itaque tum Scaevola cum in eam ipsam mentionem incidisset,</p><p>exposuit nobis sermonem Laeli de amicitia habitum ab illo secum</p>\",\"template\":\"card_default\",\"style\":\"\"}]}},{\"code\":\"app.component_cards\",\"data\":{\"title\":\"En quelques chiffres clés\",\"content\":null,\"template\":\"cards_key_figures\",\"style\":\"key-figures\",\"cards\":[{\"title\":\"356\",\"subtitle\":null,\"image\":\"/media/image/lowangleviewscafoldingbuilding-620e5f4021b25.jpg\",\"alt\":\"structure métallique\",\"link\":null,\"content\":\"<p>Itaque tum Scaevola cum in</p><p>eam ipsam mentio</p>\",\"template\":\"card_default\",\"style\":\"\"},{\"title\":\"70\",\"subtitle\":null,\"image\":\"/media/image/lowangleviewscafoldingbuilding-620e5fde8bac0.jpg\",\"alt\":\"structure métallique\",\"link\":null,\"content\":\"<p>Itaque tum Scaevola cum in</p><p>eam ipsam mentio</p>\",\"template\":\"card_default\",\"style\":\"\"},{\"title\":\"4 560\",\"subtitle\":null,\"image\":\"/media/image/lowangleviewscafoldingbuilding-620e5fde8bf37.jpg\",\"alt\":\"structure métallique\",\"link\":null,\"content\":\"<p>Itaque tum Scaevola cum in</p><p>eam ipsam mentio</p>\",\"template\":\"card_default\",\"style\":\"\"}]}},{\"code\":\"app.component_cards\",\"data\":{\"title\":\"175 ans d\'histoire\",\"content\":\"<h3><br></h3>\",\"template\":\"cards_default\",\"style\":\"two-photos\",\"cards\":[{\"title\":null,\"subtitle\":null,\"image\":\"/media/image/concretewallcementfloorcopyspace-620e65848ea23.jpg\",\"alt\":\"Détail d\'un mur en béton\",\"link\":\"http://localhost:8887/fr_FR/\",\"content\":\"<h3><span style=\\\"font-weight: normal;\\\">Les 175 ans d\'histoire<br>du </span>Groupe Brochard</h3><p>Ipsam vero urbem Byzantiorum fuisse refertissimam atque ornatissimam signis quis ignorat? Quae illi, exhausti sumptibus bellisque maximis, cum omnis Mithridaticos impetus totumque Pontum armatum affervescentem in Asiam atque erumpentem, ore repulsum et cervicibus interclusum suis sustinerent.</p>\",\"template\":\"card_default\",\"style\":\"\"},{\"title\":null,\"subtitle\":null,\"image\":\"/media/image/lowangleviewscafoldingbuilding-620e65848ee10.jpg\",\"alt\":\"structure métallique\",\"link\":null,\"content\":null,\"template\":\"card_default\",\"style\":\"\"}]}},{\"code\":\"app.component_cards\",\"data\":{\"title\":\"Configurateur 3D & Services disponibles\",\"content\":null,\"template\":\"cards_default\",\"style\":\"two-cards-in-line\",\"cards\":[{\"title\":\"Configurateur 3D\",\"subtitle\":null,\"image\":\"/media/image/projet3dsalledebainsgedimat-620cd11352402.jpg\",\"alt\":null,\"label\":\"Concevez votre projet\",\"link\":\"http://localhost:8887/fr_FR/\",\"content\":\"<p>Envie \'une nouvelle salle de bains ?</p><p>Votre salle de bain, du carrelage aux meubles</p>\",\"template\":\"card_default\",\"style\":\"\"},{\"title\":\"Les services disponibles\",\"subtitle\":null,\"image\":\"/media/image/projet3dsalledebainsgedimat-620d05f89d209.jpg\",\"alt\":null,\"label\":\"En savoir plus\",\"link\":\"http://localhost:8887/fr_FR/\",\"content\":\"<p>Ipsam vero urbem Byzantiorum fuisse</p><p>refertissimam atque ornatissimam signis</p>\",\"template\":\"card_default\",\"style\":\"bg-dark-gray\"}]}},{\"code\":\"app.component_cards\",\"data\":{\"title\":\"Nos produits\",\"content\":\"<p><br></p>\",\"template\":\"cards_default\",\"style\":\"product-catalogs\",\"cards\":[{\"title\":\"Retrouvez nos produits\",\"subtitle\":\"dans les catalogues\",\"image\":\"/media/image/catalogues-62138efbe6bdc.png\",\"alt\":\"Catalogues Gedimat\",\"label\":\"Tous les catalogues\",\"link\":\"http://localhost:8887/fr_FR/\",\"content\":\"<p>Ipsam vero urbem Byzantiorum fuisse refertissimam atque ornatissimam signis quis ignorat?</p><p><ul><li>catalogue Intérieurs</li><li>Catalogue Menuiserie</li><li>Catalogue Extérieurs</li><li>Catalogue Tendances</li><li>Catalogue Outillage</li></ul></p>\",\"template\":\"card_default\",\"style\":\"\"}]}},{\"code\":\"app.component_cards\",\"data\":{\"title\":\"Tutos, tendances & actus\",\"content\":null,\"template\":\"cards_tutos_news\",\"style\":\"tutos-news\",\"cards\":[]}},{\"code\":\"app.component_slider\",\"data\":{\"title\":\"Les bonnes affaires\",\"content\":null,\"template\":\"slider_products\",\"style\":\"products\",\"cards\":[]}},{\"code\":\"app.component_cards\",\"data\":{\"designation\":\"des 1\",\"title\":\"test\",\"content\":null,\"template\":\"cards_default\",\"style\":\"\",\"cards\":[{\"designation\":null,\"title\":\"item 1\",\"subtitle\":null,\"primaryImage\":null,\"image\":null,\"alt\":null,\"label\":null,\"content\":null,\"icon\":null,\"web_page_link\":{\"web_page\":{},\"name\":null},\"article_link\":{\"article\":null,\"name\":null},\"external_link\":{\"value\":null,\"name\":null},\"template\":\"card_default\",\"style\":\"\"}]}}]','fr_FR');
