INSERT INTO `app_web_page_translation` VALUES (1,1,'Qui sommes nous ?',NULL,NULL,NULL,NULL,'Qui sommes nous',NULL,'[{\"code\":\"app.component_hero\",\"data\":{\"devkey\":null,\"title\":null,\"content\":null,\"image\":\"/media/image/gedimat_stamand1301920x640-622b2a0ff22d3.jpg\",\"alt\":\"fer à beéton et treillis soudé\",\"label\":null,\"link\":null,\"template\":\"hero_default\",\"style\":\"\"}},{\"code\":\"app.component_breadcrumb\",\"data\":{\"title\":null,\"template\":\"breadcrumb_default\",\"style\":\"\"}},{\"code\":\"app.component_page_header\",\"data\":{\"title\":\"Qui sommes nous ?\",\"content\":\"psam vero urbem Byzantiorum fuisse refertissimam atque ornatissimam signis quis ignorat? Quae illi, exhausti sumptibus bellisque maximis, cum omnis Mithridaticos impetus totumque Pontum armatum affervescentem in Asiam atque erumpentem, ore repulsum et cervicibus interclusum suis sustinerent.\",\"template\":\"page_header_default\",\"style\":\"\"}},{\"code\":\"app.component_slider\",\"data\":{\"designation\":\"Slider Histoire\",\"title\":null,\"content\":null,\"template\":\"slider_history\",\"style\":\"history\",\"cards\":[{\"designation\":null,\"title\":null,\"subtitle\":null,\"primaryImage\":null,\"image\":null,\"alt\":null,\"label\":null,\"content\":\"<h3>1845-2021</h3><p>LE GROUPE BROCHARD,</p><p>176 ANS D’HISTOIRE</p><p>7 GÉNÉRATIONS</p>\",\"icon\":null,\"web_page_link\":{\"web_page\":{},\"name\":null},\"article_link\":{\"article\":null,\"name\":null},\"external_link\":{\"value\":null,\"name\":null},\"template\":\"card_slider_history_intro\",\"style\":\"\"},{\"designation\":null,\"title\":null,\"subtitle\":null,\"primaryImage\":null,\"image\":\"/media/image/carte01-622f02d0a1c23.jpg\",\"alt\":\"ancienne carte de visite Briqueteries & Tuileries Mécaniques\",\"label\":null,\"content\":\"<h3><span style=\\\"font-weight: normal;\\\">Napoléon III décide de faire de Bourges&nbsp;une ville d’armement. Suite à cette décision,&nbsp;</span>Pierre Brochard,<span style=\\\"font-weight: normal;\\\"> ouvrier potier de terre, quitte la Tuilerie d’Issy (Chartres) et&nbsp;</span>arrive à Bourges<span style=\\\"font-weight: normal;\\\">&nbsp;avec sa femme et ses enfants.</span></h3>\",\"icon\":null,\"web_page_link\":{\"web_page\":{},\"name\":null},\"article_link\":{\"article\":null,\"name\":null},\"external_link\":{\"value\":null,\"name\":null},\"template\":\"card_slider_history_item\",\"style\":\"\"},{\"designation\":null,\"title\":\"Titre test carte item 2\",\"subtitle\":null,\"primaryImage\":null,\"image\":\"/media/image/brique1-622f02d0a2372.png\",\"alt\":null,\"label\":null,\"content\":\"<h3><span style=\\\"font-weight: normal;\\\">LE CHOIX DE<br></span>BOURGES</h3><p>EST STRATÉGIQUE ET POLITIQUE</p><p>Stratégique car <b>Bourges est éloigné des frontières et à l’abri des invasions.</b></p><p>Politique car <b>Napoléon III répond à une demande des pouvoirs publics locaux qui réclament à l’État des décentralisations.</b></p>\",\"icon\":null,\"web_page_link\":{\"web_page\":{},\"name\":null},\"article_link\":{\"article\":null,\"name\":null},\"external_link\":{\"value\":null,\"name\":null},\"template\":\"card_slider_history_item\",\"style\":\"\"}]}},{\"code\":\"app.component_slider\",\"data\":{\"designation\":\"Slider Histoire\",\"title\":null,\"content\":null,\"template\":\"slider_history\",\"style\":\"history\",\"cards\":[{\"designation\":\"Intro 1\",\"title\":null,\"subtitle\":null,\"primaryImage\":null,\"image\":null,\"alt\":null,\"label\":null,\"content\":\"<h3>1845-2021</h3><p>LE GROUPE BROCHARD,</p><p>176 ANS D’HISTOIRE</p><p>7 GÉNÉRATIONS</p>\",\"icon\":null,\"web_page_link\":{\"web_page\":{},\"name\":null},\"article_link\":{\"article\":null,\"name\":null},\"external_link\":{\"value\":null,\"name\":null},\"template\":\"card_default\",\"style\":\"\"}]}},{\"code\":\"app.component_slider\",\"data\":{\"designation\":null,\"title\":null,\"content\":null,\"template\":\"slider_history\",\"style\":\"history\",\"cards\":[{\"designation\":null,\